import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, Optional

import requests


DATADOG_API_BASE = "https://api.datadoghq.com/api/v1"


class DatadogMetricsError(Exception):
    pass


def get_metric_aggregates(
    metric_name: str,
    start: datetime,
    end: datetime,
    aggregator: str = "avg",
    api_key: Optional[str] = None,
    app_key: Optional[str] = None,
    api_base: str = DATADOG_API_BASE,
) -> Dict[str, Any]:
    api_key = api_key or os.environ.get("DATADOG_API_KEY")
    app_key = app_key or os.environ.get("DATADOG_APP_KEY")

    if not api_key or not app_key:
        raise DatadogMetricsError(
            "Missing Datadog credentials. Set DATADOG_API_KEY and DATADOG_APP_KEY."
        )

    if start.tzinfo is None:
        start = start.replace(tzinfo=timezone.utc)
    if end.tzinfo is None:
        end = end.replace(tzinfo=timezone.utc)

    start_ts = int(start.timestamp())
    end_ts = int(end.timestamp())

    if end_ts <= start_ts:
        raise DatadogMetricsError("end must be after start")

    query = f"{aggregator}:{metric_name}{{*}}"

    resp = requests.get(
        f"{api_base}/query",
        headers={
            "DD-API-KEY": api_key,
            "DD-APPLICATION-KEY": app_key,
            "Accept": "application/json",
        },
        params={
            "from": start_ts,
            "to": end_ts,
            "query": query,
        },
        timeout=30,
    )

    if resp.status_code >= 400:
        raise DatadogMetricsError(
            f"Datadog API error {resp.status_code}: {resp.text}"
        )

    data = resp.json()
    series = data.get("series", [])

    values = []
    points = []
    for s in series:
        for point in s.get("pointlist", []):
            if not isinstance(point, list) or len(point) != 2:
                continue
            ts_ms, value = point
            if value is None:
                continue
            points.append(
                {
                    "timestamp": datetime.fromtimestamp(
                        ts_ms / 1000.0, tz=timezone.utc
                    ).isoformat(),
                    "value": float(value),
                }
            )
            values.append(float(value))

    aggregated_value: Optional[float]
    if not values:
        aggregated_value = None
    elif aggregator == "sum":
        aggregated_value = sum(values)
    elif aggregator == "min":
        aggregated_value = min(values)
    elif aggregator == "max":
        aggregated_value = max(values)
    elif aggregator == "avg":
        aggregated_value = sum(values) / len(values)
    else:
        aggregated_value = None

    return {
        "provider": "Datadog",
        "metric": metric_name,
        "query": query,
        "aggregator": aggregator,
        "start": start.isoformat(),
        "end": end.isoformat(),
        "point_count": len(points),
        "aggregated_value": aggregated_value,
        "points": points,
        "raw": data,
    }


def get_last_hour_metric_average(metric_name: str) -> Dict[str, Any]:
    end = datetime.now(timezone.utc)
    start = end - timedelta(hours=1)
    return get_metric_aggregates(metric_name=metric_name, start=start, end=end, aggregator="avg")
